    fun svg(nom: String, classe: String = "ico"): String =
        CHEMINS[nom]?.let { "<svg class=\"$classe\" viewBox=\"0 -960 960 960\" aria-hidden=\"true\"><path d=\"$it\"/></svg>" }.orEmpty()
}
